  // prose blocks on one physical row. Join those owners without extending the
  // separate reading-order envelopes or acquiring any intervening math owner.
  for (const prefix of [...blocks]) {
    if (
      !blocks.includes(prefix) ||
      prefix.lines.length !== 1 ||
      prefix.items[0].str !== 'where' ||
      prefix.risks.length ||
      prefix.lines.some((line) => preservedFormulaLines.has(line))
    )
      continue
    const native = [...prefix.items].sort((a, b) => a.index - b.index),
      first = native[0],
      last = native.at(-1)!,
      font = first.font,
      next = all.find((item) => item.index > last.index),
      tail = next && blocks.find((block) => block !== prefix && block.items.includes(next))
    // An indexed function can be the subject when its callee label is one
    // native token and the argument index is attached on the same row.
    const [, base, label] = native,
      argumentIndex = native.at(-2)!,
      argument = native.at(-3)!
    const indexedFunction =
      base &&
      label &&
      /^[A-Z]$/u.test(base.str) &&
      /^[A-Z]{2,8}$/u.test(label.str) &&
      label.font >= font * 0.6 &&
      label.font < font * 0.85 &&
      label.originalBaseline - base.originalBaseline > font * 0.05 &&
      label.originalBaseline - base.originalBaseline < font * 0.5 &&
      Math.abs(label.x - base.right) < font * 0.1 &&
      native[3]?.str === '(' &&
      native.at(-1)?.str === ')' &&
      /^[a-z]$/u.test(argument.str) &&
      /^[a-z\d]$/u.test(argumentIndex.str) &&
      /^\([a-z](?:\|[a-z])?[a-z\d]\)$/u.test(
        native
          .slice(3)
          .map((item) => item.str)
          .join('')
      ) &&
      attachedScripts.has(argumentIndex) &&
      argumentIndex.originalBaseline - argument.originalBaseline > font * 0.05 &&
      Math.abs(argumentIndex.x - argument.right) < font * 0.1 &&
      native.every(
        (item) =>
          nativeHorizontalSourceItem(item) && item.nativeLine === first.nativeLine && !item.hasEOL
      ) &&
      next?.nativeLine === first.nativeLine
    if (
      !tail ||
      tail.risks.length ||
      !/^(?:are|is|denotes) [a-z]/u.test(tail.source) ||
      wordCount(tail.source) < 6 ||
      tail.lines.some((line) => preservedFormulaLines.has(line)) ||
      !first.fontName ||
      next!.fontName !== first.fontName ||
      Math.min(...tail.items.map((item) => item.index)) !== next!.index ||
      Math.abs(next!.font - font) >= font * 0.05 ||
      Math.abs(next!.originalBaseline - first.originalBaseline) >= font * 0.05 ||
      next!.x - last.right < -font * 0.05 ||
      next!.x - last.right >= font * 0.8 ||
      native
        .slice(1)
        .some(
          (item) =>
            (!(indexedFunction && (item === label || item.str === '|')) &&
              !/^(?:[, ]*and|[, ]*[A-Za-z\p{Script=Greek}]|(?:\u0302|[\dˆ′(),.])+)$/u.test(
                item.str.trim()
              )) ||
            item.font < font * 0.6 ||
            item.font > font * 1.05 ||
            Math.abs(item.originalBaseline - first.originalBaseline) > font * 0.55
        ) ||
      !native.some(
        (item, at) =>
          attachedScripts.has(item) ||
          (item.str === '′' &&
            at > 0 &&
            /^[A-Za-z\p{Script=Greek}]$/u.test(native[at - 1].str) &&
            item.index === native[at - 1].index + 1 &&
            item.font < font * 0.85 &&
            native[at - 1].originalBaseline - item.originalBaseline > font * 0.1 &&
            item.x - native[at - 1].right >= -font * 0.05 &&
            item.x - native[at - 1].right < font * 0.15)
      ) ||
      native.some((item, at) =>
        at
          ? all.some((other) => other.index > native[at - 1].index && other.index < item.index)
          : false
      ) ||
      [...native, ...tail.items].some(
        (item) => item.unsupported || tableItems.has(item) || codeItems.has(item)
      )
    )
      continue
    const variables = prefix.source.slice('where'.length)
    let depth = 0
    const unbalanced = [...variables].some((char) => {
      depth += Number(char === '(') - Number(char === ')')
      return depth < 0
    })
    if (
      unbalanced ||
      depth !== 0 ||
      !tail.lines.some(
        (line) =>
          wordCount(line.text) >= 8 &&
          !symbolicExpression(line.text) &&
          Math.abs(line.x - prefix.x) < font * 0.45 &&
          Math.abs(line.right - tail.right) < font * 0.45 &&
          line.baseline - first.originalBaseline > font * 0.75 &&
          line.baseline - first.originalBaseline < font * 4 &&
          line.items[0].fontName === first.fontName &&
          line.items.at(-1)!.fontName === first.fontName
      )
    )
      continue
    prefix.source = joinLines(prefix.source, tail.source)
    if (indexedFunction)
      prefix.lines = [lineOf([...native, ...tail.lines[0].items]), ...tail.lines.slice(1)]
    else prefix.lines.push(...tail.lines)
    prefix.items.push(...tail.items)
    Object.assign(prefix, bounds(prefix.items))
    blocks.splice(blocks.indexOf(tail), 1)
  }
  for (const [tail, predecessor] of acronymSentenceTails) {
    const finish = blocks.find((block) => block.items.length === 1 && block.items[0] === tail)
    const owner = blocks.find((block) => block.items.at(-1) === predecessor)
    if (!finish || !owner || owner.lines.length < 2 || owner.sourceOnly || owner.risks.length)
      continue
    owner.lines.push(...finish.lines)
    owner.source = joinLines(owner.source, finish.source)
    owner.items.push(tail)
    Object.assign(owner, bounds(owner.items))
    blocks.splice(blocks.indexOf(finish), 1)
  }
  const parallelCaptions = nativeParallelFigureCaptions(blocks, page, all, tableItems, codeItems)
  if (parallelCaptions) blocks.splice(0, blocks.length, ...parallelCaptions)
  blocks.push(...panelCaptionBlocks)
  const duplicateCaptionAnchors = all
    .filter((item) => captionAnchorLabel.test(item.str))
    .flatMap((item, index, anchors) =>
      anchors.slice(index + 1).flatMap((other) => {
        const sameLabel =
          item.str.replace(/[.:]$/u, '').toLowerCase() ===
          other.str.replace(/[.:]$/u, '').toLowerCase()
        const font = Math.max(item.font, other.font)
        const overlapping =
          item.x < other.right + font * 0.8 &&
          other.x < item.right + font * 0.8 &&
          Math.abs(item.originalBaseline - other.originalBaseline) < font * 0.9
        return sameLabel && overlapping ? [{ item, other }] : []
      })
    )
  if (duplicateCaptionAnchors.length) {
    for (const block of blocks) {
      if (!block.items.length) continue
      const anchor = duplicateCaptionAnchors.find(({ item, other }) => {
        const anchorBlocks = blocks.filter(
          (candidate) => candidate.items.includes(item) || candidate.items.includes(other)
        )
        if (
          !anchorBlocks.some((candidate) => {
            const source = collapseDuplicateCaptionLabels(candidate.source)
            return isPdfTranslationCaption(source) && !captionBodyReference.test(source)
          })
        )
          return false
        const top = Math.min(item.y, other.y),
          bottom = Math.max(item.bottom, other.bottom),
          left = Math.min(item.x, other.x),
          right = Math.max(item.right, other.right),
          font = Math.max(item.font, other.font),
          anchorFonts = new Set(
            blocks
              .filter(
                (candidate) => candidate.items.includes(item) || candidate.items.includes(other)
              )
              .flatMap((candidate) => candidate.items.map((entry) => entry.fontName))
              .filter((name): name is string => !!name)
          ),
          streamFonts = new Set(
            block.items.map((entry) => entry.fontName).filter((name): name is string => !!name)
          ),
          anchorIndexGap = Math.abs(item.index - other.index),
          lowerAnchorIndex = Math.min(item.index, other.index),
          upperAnchorIndex = Math.max(item.index, other.index),
          anchorBaselineGap = Math.abs(item.originalBaseline - other.originalBaseline),
          carriesBothStreams =
            [...streamFonts].filter((name) => anchorFonts.has(name)).length >= 2 ||
            block.items.some((left, index) =>
              block.items.slice(index + 1).some((right) => {
                const pairFont = Math.max(left.font, right.font),
                  sameNativeGap =
                    Math.abs(Math.abs(left.index - right.index) - anchorIndexGap) <=
                    Math.max(4, anchorIndexGap * 0.15),
                  sameBaselineGap =
                    Math.abs(
                      Math.abs(left.originalBaseline - right.originalBaseline) - anchorBaselineGap
                    ) <=
                    pairFont * 0.35,
                  sameAnchorX =
                    (Math.abs(left.x - item.x) <= pairFont * 0.8 &&
                      Math.abs(right.x - other.x) <= pairFont * 0.8) ||
                    (Math.abs(left.x - other.x) <= pairFont * 0.8 &&
                      Math.abs(right.x - item.x) <= pairFont * 0.8),
                  straddlesAnchors =
                    (left.index < lowerAnchorIndex && right.index > upperAnchorIndex) ||
                    (right.index < lowerAnchorIndex && left.index > upperAnchorIndex)
                return sameNativeGap && sameBaselineGap && sameAnchorX && straddlesAnchors
              })
            )
        return (
          (block.items.includes(item) || block.items.includes(other) || carriesBothStreams) &&
          block.x < right + font * 0.8 &&
          block.right > left - font * 0.8 &&
          block.y < bottom + Math.max(item.font, other.font) * 1.8 &&
          block.bottom > top - Math.max(item.font, other.font) * 1.8
        )
      })
      if (anchor) block.sourceOnly = true
    }
  }
  for (const item of all.filter((i) => isolatedFolios.has(i.key)))
    blocks.push({
      ...item,
      source: item.str,
      lines: [],
      items: [item],
      risks: []
    })
  for (const item of all.filter(
    (i) =>
      !panelCaptionItems.has(i) &&
      (i.unsupported || i.detachedOperator || embeddedMetadata.has(i) || plotTicks.has(i))
  ))
    blocks.push({
      ...item,
      source: item.str,
      ...(plotTicks.has(item) ? { sourceOnly: true as const } : {}),
      lines: [],
      items: [item],
      risks: [
        item.unsupported
          ? 'unsupported-orientation'
          : embeddedMetadata.has(item)
            ? 'metadata-extraction'
            : 'formula-extraction'
      ]
    })
  // Rotated margin stamps and centered page numbers must not bridge column
  // gutters and interleave otherwise independent body text.
  const footers = new Set(
    blocks.filter(
      (block) =>
        block.items.some((i) => isolatedFolios.has(i.key)) ||
        (/^\d{1,4}$/u.test(block.source.trim()) &&
          block.y > page.height * 0.88 &&
          Math.abs((block.x + block.right) / 2 - page.width / 2) < page.width * 0.1)
    )
  )
  // A margin row can be painted after body prose in the native stream.
  // Detach it from the completed block while keeping the body paragraph boundary.
  for (const block of [...blocks]) {
    const [header, ...body] = block.lines
    if (
      block.sourceOnly ||
      block.risks.length ||
      !body.length ||
      !header.items.every((item) => pairedHeaders.has(item.key)) ||
      body.some((line) => line.items.some((item) => pairedHeaders.has(item.key))) ||
      !block.source.startsWith(header.text + ' ')
    )
      continue
    const items = body.flatMap((line) => line.items)
    blocks.splice(
      blocks.indexOf(block),
      1,
      { ...header, lines: [header], source: header.text, risks: [] },
      {
        ...block,
        ...bounds(items),
        font: body[0].font,
        lines: body,
        items,
        source: block.source.slice(header.text.length + 1)
      }
    )
  }
  const headers = new Set(
    blocks.filter((block) => block.items.every((item) => runningHeaders.has(item.key)))
  )
  // Treat the proved row as one XY-cut envelope, then return its unchanged
  // fragment objects in native interval order. Never merge their source text.
  const nativeInlineBlockGroups = new Map<Block, Block[]>()
  let flowBlocks = blocks.filter(
    (block) =>
      !headers.has(block) && !footers.has(block) && !block.risks.includes('unsupported-orientation')
  )
  // A proved listing and its native caption occupy one reading-order frame.
  // Keep the individual text owners; only prevent XY-cut from reading a short
  // left-aligned import before its centered caption above.
  for (const owned of listingPackets) {
    const parts = flowBlocks.filter((block) => block.items.some((item) => owned.has(item)))
    if (
      parts.length < 2 ||
      parts.some((block) => block.items.some((item) => !owned.has(item))) ||
      [...owned].some((item) => parts.filter((block) => block.items.includes(item)).length !== 1)
    )
      continue
    const items = [...owned],
      grouped: Block = {
        ...bounds(items),
        font: median(items.map((item) => item.font)),
        source: '',
        items,
        lines: [],
        risks: []
      }
    nativeInlineBlockGroups.set(
      grouped,
      parts.sort(
        (a, b) =>
          Math.min(...a.items.map((item) => item.index)) -
          Math.min(...b.items.map((item) => item.index))
      )
    )
    flowBlocks = [...flowBlocks.filter((block) => !parts.includes(block)), grouped]
  }
  for (const row of nativeInlineRows) {
    const owned = new Set(row.items),
      parts = flowBlocks.filter((block) => block.items.some((item) => owned.has(item)))
    if (
      parts.length < 2 ||
      parts.some((block) => block.items.some((item) => !owned.has(item))) ||
      row.items.some((item) => parts.filter((block) => block.items.includes(item)).length !== 1)
    )
      continue
    const grouped: Block = {
      ...bounds(row.items),
      font: row.font,
      source: '',
      items: row.items,
      lines: [],
      risks: []
    }
    nativeInlineBlockGroups.set(
      grouped,
      parts.sort(
        (a, b) =>
          Math.min(...a.items.map((item) => item.index)) -
          Math.min(...b.items.map((item) => item.index))
      )
    )
    flowBlocks = [...flowBlocks.filter((block) => !parts.includes(block)), grouped]
  }

  const ordered = [
    ...headers,
    ...(
      nativeNumberedReferenceColumns(flowBlocks, page) ??
      nativeTerminalColumnOrder(flowBlocks, page) ??
      (nativeInlineBlockGroups.size === 0
        ? nativeStaggeredColumnBodyOrder(flowBlocks, page, readingOrder)
        : undefined) ??
      readingOrder(flowBlocks)
    ).flatMap((block) => nativeInlineBlockGroups.get(block) ?? [block]),
    ...footers,
    ...blocks.filter(
      (block) => !footers.has(block) && block.risks.includes('unsupported-orientation')
    )
  ]
  // A body line can be divided after the variable of an inline definition.
  // Keep the assignment and its copula together when one justified row proves the seam.
  for (let index = 0; index + 2 < ordered.length; index++) {
    const [head, body, witness] = ordered.slice(index, index + 3)
    if (
      !/^where [A-Z] = [A-Z]\([A-Z] [−-] [a-z]\) and [a-z]$/u.test(head.source) ||
      !/^is (?:a|an|the) /u.test(body.source) ||
      !terminal(body.source) ||
      head.lines.length !== 1 ||
      body.lines.length !== 2 ||
      [head, body, witness].some((block) => block.sourceOnly || block.risks.length)
    )
      continue
    const [left] = head.lines,
      [right, lower] = body.lines,
      lead = left.items[0],
      last = left.items.at(-1)!,
      next = right.items[0],
      peer = witness.lines[0],
      h = lead.font,
      topRow = [...left.items, ...right.items],
      items = [...topRow, ...lower.items],
      same = (a: number, b: number, tolerance: number): boolean => Math.abs(a - b) < h * tolerance
    if (
      !peer ||
      lead.str !== 'where' ||
      !lead.fontName ||
      !/^[a-z]$/u.test(last.str) ||
      last.fontName === lead.fontName ||
      !/^is (?:a|an|the)\s/u.test(next.str) ||
      wordCount(next.str) < 6 ||
      wordCount(peer.text) < 12 ||
      !/^\p{Lu}/u.test(peer.text) ||
      lead.fontName !== next.fontName ||
      lead.fontName !== right.items.at(-1)!.fontName ||
      lead.fontName !== lower.items[0].fontName ||
      lead.fontName !== peer.items[0].fontName ||
      lead.fontName !== peer.items.at(-1)!.fontName ||
      !right.items.at(-1)!.hasEOL ||
      !lower.items.at(-1)!.hasEOL ||
      last.hasEOL ||
      !same(right.right, peer.right, 0.18) ||
      !same(left.x, lower.x, 0.1) ||
      peer.x - left.x < h ||
      peer.x - left.x > h * 2 ||
      !same(right.baseline - left.baseline, 0, 0.03) ||
      lower.baseline - right.baseline < h ||
      lower.baseline - right.baseline > h * 1.45 ||
      !same(peer.baseline - lower.baseline, lower.baseline - right.baseline, 0.07) ||
      next.x - last.right < 0 ||
      next.x - last.right > h * 0.45 ||
      topRow.some(
        (item) =>
          item.nativeLine !== lead.nativeLine ||
          !same(item.font, h, 0.02) ||
          !same(item.originalBaseline, lead.originalBaseline, 0.03)
      ) ||
      items.some(
        (item, n) =>
          !nativeHorizontalSourceItem(item) ||
          tableItems.has(item) ||
          codeItems.has(item) ||
          embeddedMetadata.has(item) ||
          (n > 0 &&
            (item.index <= items[n - 1].index ||
              page.items.slice(items[n - 1].index + 1, item.index).some((part) => part.str.trim())))
      ) ||
      page.items.slice(items.at(-1)!.index + 1, peer.items[0].index).some((part) => part.str.trim())
    )
      continue
    const row = lineOf(topRow)
    const kept = new Set(items)
    const box = bounds(items)
    if (
      box.x < 0 ||
      box.y < 0 ||
      box.right > page.width ||
      box.bottom > page.height ||
      all.some(
        (item) =>
          !kept.has(item) &&
          item.x < box.right &&
          item.right > box.x &&
          item.y < box.bottom &&
          item.bottom > box.y
      )
    )
      continue
    ordered.splice(index, 2, {
      ...body,
      ...box,
      items,
      lines: [row, lower],
      source: joinCaptionLines([head.source, body.source], lexicon)
    })
  }
  const separatedProse = new Set<Block>(),
    separatedMath = new Set<Block>()
  const finalOrdered = ordered.flatMap<Block>((block, index) => {
    const [closing, support] = block.lines,
      [end] = closing?.items ?? [],
      [label, sponsor] = support?.items ?? []
    // The short last sentence in a column can sit immediately above smaller
    // end matter with a bold run-in label. Keep the native rows distinct.
    if (
      closing &&
      support &&
      closing.items.length === 1 &&
      sponsor &&
      label.str === 'Funding.' &&
      /^[a-z]+(?: [a-z-]+){2,6}\.$/u.test(end.str) &&
      wordCount(sponsor.str) >= 4 &&
      !block.sourceOnly &&
      !block.risks.some((risk) => risk !== 'possible-continuation') &&
      block.items.every(
        (item) => !item.unsupported && !tableItems.has(item) && !codeItems.has(item)
      ) &&
      end.x > page.width * 0.5 &&
      end.y < page.height * 0.12 &&
      nativeHorizontalSourceItem(end) &&
      nativeHorizontalSourceItem(label) &&
      nativeHorizontalSourceItem(sponsor) &&
      end.fontName === sponsor.fontName &&
      end.fontName !== label.fontName &&
      Math.abs(end.font - label.font) < end.font * 0.05 &&
      sponsor.font > end.font * 0.8 &&
      sponsor.font < end.font * 0.95 &&
      Math.abs(label.x - end.x) < end.font * 0.1 &&
      Math.abs(label.originalBaseline - sponsor.originalBaseline) < end.font * 0.05 &&
      label.originalBaseline - end.originalBaseline > end.font &&
      label.originalBaseline - end.originalBaseline < end.font * 2 &&
      ordered.slice(index + 1, index + 4).some((peer) => {
        const [head, companion] = peer.items
        return (
          /^(?:Acknowledgements|Acknowledgments)\.$/u.test(head.str) &&
          head.fontName === label.fontName &&
          companion?.fontName === sponsor.fontName &&
          Math.abs(head.x - label.x) < end.font * 0.15 &&
          Math.abs(head.originalBaseline - companion.originalBaseline) < end.font * 0.05
        )
      })
    ) {
      const rest = block.items.slice(1),
        lines = block.lines.slice(1)
      verifiedProseLines.add(closing)
      return [
        { ...closing, source: closing.text, items: [end], lines: [closing], risks: [] },
        {
          ...block,
          ...bounds(rest),
          source: lines.map((line) => line.text).join(' '),
          items: rest,
          lines
        }
      ]
    }

    if (
      block.lines.length !== 1 ||
      block.risks.length ||
      headers.has(block) ||
      footers.has(block) ||
      block.items.some((item) => tableItems.has(item) || codeItems.has(item) || item.unsupported)
    )
      return [block]
    const connectors = block.items.filter((item) =>
      /^(?:[,;.] )?(?:and hence|and therefore|therefore|thus|and so)$/u.test(item.str)
    )
    if (connectors.length !== 1 || block.items.length < 3) return [block]
    const connector = connectors[0],
      font = connector.font,
      row = inlineNativeInventory.get(connector.nativeLine)
    if (
      !connector.fontName ||
      !row ||
      !finalizedLines.has(connector.nativeLine) ||
      row.some(
        (item, i) =>
          item.unsupported ||
          tableItems.has(item) ||
          codeItems.has(item) ||
          !item.fontName ||
          ![item.x, item.y, item.right, item.bottom].every(Number.isFinite) ||
          item.width <= 0 ||
          Math.abs(item.originalBaseline - connector.originalBaseline) > font * 0.5 ||
          item.font < font * 0.6 ||
          item.font > font * 1.05 ||
          (i > 0 &&
            (item.x < row[i - 1].right - font * 0.05 || item.x > row[i - 1].right + font * 0.8))
      )
    )
      return [block]
    const rowBounds = bounds(row),
      rowSet = new Set<Item>(row),
      domain = nativeProseProofDomain(row)
    if (!domain || all.some((item) => !rowSet.has(item) && nativeTextOverlapsProof(item, domain)))
      return [block]
    const peers = all.filter(
      (item) =>
        item.fontName === connector.fontName &&
        !rowSet.has(item) &&
        !item.unsupported &&
        !tableItems.has(item) &&
        !codeItems.has(item) &&
        Math.abs(item.font - font) < font * 0.05 &&
        Math.abs(item.originalBaseline - connector.originalBaseline) < font * 12 &&
        (item.str.match(/[A-Za-z]{2,}/gu)?.length ?? 0) >= 8 &&
        !symbolicExpression(item.str)
    )
    if (
      peers.length < 2 ||
      !peers.some(
        (item) =>
          Math.abs(item.x - rowBounds.x) < font * 0.25 &&
          Math.abs(item.originalBaseline - connector.originalBaseline) < font * 12
      )
    )
      return [block]
    const math = block.items.filter((item) => item !== connector)
    if (
      !math.some((item) => item.fontName !== connector.fontName) ||
      !symbolicExpression(lineOf([...math]).text) ||
      block.items.some((item) => !rowSet.has(item)) ||
      block.items.some((item, i) => i > 0 && item.index <= block.items[i - 1].index)
    )
      return [block]
    const at = block.items.indexOf(connector)
    return [block.items.slice(0, at), [connector], block.items.slice(at + 1)]
      .filter((items) => items.length)
      .map((items) => {
        const line = lineOf([...items]),
          part: Block = { ...line, source: line.text, items, lines: [line], risks: [] }
        if (items[0] === connector) separatedProse.add(part)
        else separatedMath.add(part)
        return part
      })
  })
  // A decorative initial can occupy two inset rows although PDF.js has split
  // the first row into words. Retain that exact first-row owner: its native
  // bounds overlap the adjacent body owner even when the two inks do not.
  const ownersByItem = new Map(
    finalOrdered.flatMap((owner) => owner.items.map((part) => [part, owner] as const))
  )
