    !!owner &&
    !owner.risks.length &&
    owner.fragments.length === 1 &&
    owner.fragments[0].page === page &&
    owner.items.length === owner.originalStrings.length &&
    owner.items.every(
      (key, at) =>
        key.startsWith(`${page}:`) &&
        native(Number(key.split(':')[1]))?.item.str === owner.originalStrings[at]
    )
