    complete(owner) &&
    !!owner.sourceOnly &&
    symbolicExpression(owner.source) &&
    (!/[A-Za-z]{3,}/u.test(owner.source) ||
      (prefix && nativeSubscriptedDefinition(owner, raw, page, raw[index]))) &&
    ![...owner.source].some(undecodedGlyph)
